def deep_equal(a, b) -> bool:
    # If both are dicts, compare keys and values recursively
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        for key in a:
            if not deep_equal(a[key], b[key]):
                return False
        return True

    # If both are lists, compare elements in order recursively
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        for i in range(len(a)):
            if not deep_equal(a[i], b[i]):
                return False
        return True

    # If both are floats, compare with epsilon
    if isinstance(a, float) and isinstance(b, float):
        return abs(a - b) < 1e-9

    # For all other types (None, bool, int, str), exact match including type
    # Note: bool must be checked before int since bool is subclass of int
    return a == b and type(a) == type(b)
