def merge_intervals(items):
    items = sorted(items)
    result = []
    for start, end in items:
        if not result:
            result.append([start, end])
        else:
            last = result[-1]
            if start <= last[1]:
                last[1] = max(last[1], end)
            else:
                result.append([start, end])
    return result
